-- 插入初阶 5 个技能卡
INSERT INTO skill_cards (level, skill_order, title, principle, when_not_to_use, scenario_text, choices) VALUES
('初阶', 1, '先看开口时机', '不是每个安静都需要填满；先看对方有没有空、有没有回应、有没有互动机会。', '对方戴耳机、低头赶事、明显封闭、短答或回避眼神时。', '你一个人在咖啡店排队，旁边的人戴耳机、看手机、没有看向你。这时哪一个做法比较合适？', '[{"text":"A　问他：这个看起来好喝吗？","isCorrect":false,"feedback":"对方戴耳机、看手机，是明显的红灯信号。"},{"text":"B　先不打扰，专心点餐。","isCorrect":true,"feedback":"对。这不是错过机会，而是看见了红灯。好的社交判断，也包括知道什么时候不必开口。"}]'::jsonb),

('初阶', 2, '共同情境开场', '有绿灯后，不必想聪明话题；从你们共同看见、共同经历的事开始。', '对方没有开口许可，或对方明显忙碌时。', '会议还有三分钟开始，刚介绍过的同事看着会议室投影。哪一句比较自然？', '[{"text":"A　你住哪里？","isCorrect":false,"feedback":"这个问题跳过了共同情境，会让对方觉得突兀。"},{"text":"B　今天的议程看起来排得蛮满，你以前参加过这个会吗？","isCorrect":true,"feedback":"对。你从双方都在看的议程开始，也留了一个容易回答的问题。"}]'::jsonb),

('初阶', 3, '问一句，也给一点自己', '只发问像审问；只讲自己像独白。给一点自己的信息，再把球传回去。', '不必透露私人、敏感或不舒服的信息。', '新同事问你：你平时喝咖啡吗？', '[{"text":"A　有。","isCorrect":false,"feedback":"只回答一个字，对话就停了。"},{"text":"B　有，不过我常喝 Americano，不太喜欢甜的。你呢？","isCorrect":true,"feedback":"对。你回答了问题、给了一个小细节，也让对方容易接话。"}]'::jsonb),

('初阶', 4, '抓关键词接话', '不急着换成自己的故事；先抓住对方刚说的一个词，往下接一层。', '对方只给非常短的答复、明显想结束时，不要连环追问。', '对方说：我周末去跑步了。', '[{"text":"A　我最近工作很忙。","isCorrect":false,"feedback":"突然换到自己的事，打断了对方的话题。"},{"text":"B　你通常跑哪里？我最近也想多走走。","isCorrect":true,"feedback":"对。你接住了跑步，再往下问一层。"}]'::jsonb),

('初阶', 5, '自然收尾', '对话不是一定要聊长；知道怎样离开，会让开口变得更轻。', '对方短答、看回手机、身体转开、活动要开始，或话题自然结束时。', '主持人准备开始会议，对方也转向会议室。', '[{"text":"A　继续追问：你周末到底做了什么？","isCorrect":false,"feedback":"对方已经转向会议了，勉强继续会让双方都尴尬。"},{"text":"B　很高兴认识你，等会儿再聊。","isCorrect":true,"feedback":"对。你读到场合变化，也给了双方舒服的结束。"}]'::jsonb);
